from rdkit import Chem
try:
    import selfies as sf
except Exception as e:
    print('SELFIES import error:', e)
    sf=None
rs=['[C][C][=Branch1][C][=O][O][C][Branch1][C][C][=O]','[N][C][=C][C][=C][C][Branch1][Branch2][N][C][=C][N][=C][Ring1][Branch1][=C][Ring1][O]']
for s in rs:
    try:
        smi=sf.decoder(s)
        print('SELFIES:',s)
        print('SMILES:',smi)
        m=Chem.MolFromSmiles(smi)
        print('Canonical:',Chem.MolToSmiles(m) if m else None)
    except Exception as e: print('error',e)
